-- Derived from BeModel platform DDL under Apache-2.0. Industrial-only baseline.
-- Generated by forgepilot/generate.py; do not edit or run on a medical database.
CREATE TABLE IF NOT EXISTS bm_domain (
    id          BIGINT PRIMARY KEY AUTO_INCREMENT,
    code        VARCHAR(64)  NOT NULL UNIQUE COMMENT '域编码',
    name        VARCHAR(128) NOT NULL COMMENT '域名称',
    description VARCHAR(512) COMMENT '域说明',
    sort        INT DEFAULT 0,
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='业务域';

CREATE TABLE IF NOT EXISTS bm_concept (
    id          BIGINT PRIMARY KEY AUTO_INCREMENT,
    code        VARCHAR(64)  NOT NULL UNIQUE COMMENT '概念编码（全局唯一）',
    name        VARCHAR(128) NOT NULL COMMENT '标准名称',
    domain_code VARCHAR(64)  NOT NULL COMMENT '所属域',
    definition  TEXT COMMENT '业务定义',
    owner       VARCHAR(64) COMMENT '口径负责人',
    status      VARCHAR(16) DEFAULT 'DRAFT' COMMENT 'DRAFT/REVIEW/PUBLISHED/DEPRECATED',
    version     INT DEFAULT 1,
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='业务概念';

CREATE TABLE IF NOT EXISTS bm_attribute (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    concept_code VARCHAR(64) NOT NULL,
    attr_code    VARCHAR(64) NOT NULL COMMENT '属性编码',
    attr_name    VARCHAR(128) NOT NULL COMMENT '属性名称',
    data_type    VARCHAR(32) NOT NULL COMMENT 'STRING/NUMBER/DATE/ENUM',
    is_key       TINYINT DEFAULT 0 COMMENT '是否主键语义',
    definition   VARCHAR(512) COMMENT '业务含义',
    sort         INT DEFAULT 0,
    UNIQUE KEY uk_concept_attr (concept_code, attr_code)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='概念属性';

CREATE TABLE IF NOT EXISTS bm_relation (
    id            BIGINT PRIMARY KEY AUTO_INCREMENT,
    from_concept  VARCHAR(64) NOT NULL,
    to_concept    VARCHAR(64) NOT NULL,
    relation_name VARCHAR(64) NOT NULL COMMENT '关系名，如：产生/生成/结算',
    description   VARCHAR(512),
    UNIQUE KEY uk_rel (from_concept, to_concept, relation_name)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='概念关系（本体图的边）';

CREATE TABLE IF NOT EXISTS bm_term (
    id             BIGINT PRIMARY KEY AUTO_INCREMENT,
    term           VARCHAR(128) NOT NULL COMMENT '术语/方言叫法',
    concept_code   VARCHAR(64)  NOT NULL COMMENT '挂靠的标准概念',
    source_product VARCHAR(64) COMMENT '来源产品，如 HIS/LIS',
    term_type      VARCHAR(16) DEFAULT 'ALIAS' COMMENT 'STANDARD/ALIAS',
    UNIQUE KEY uk_term (term, source_product)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='业务术语库';

CREATE TABLE IF NOT EXISTS bm_metric (
    id          BIGINT PRIMARY KEY AUTO_INCREMENT,
    metric_code VARCHAR(64)  NOT NULL UNIQUE,
    name        VARCHAR(128) NOT NULL,
    definition  TEXT COMMENT '口径定义',
    formula     VARCHAR(512) COMMENT '计算公式',
    concept_code VARCHAR(64) COMMENT '绑定概念',
    owner       VARCHAR(64),
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='指标口径库';

CREATE TABLE IF NOT EXISTS bm_datasource (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    ds_code      VARCHAR(64) NOT NULL UNIQUE COMMENT '数据源编码',
    ds_name      VARCHAR(128) NOT NULL,
    product_name VARCHAR(64) COMMENT '所属产品线',
    db_type      VARCHAR(16) DEFAULT 'MYSQL',
    host         VARCHAR(128) NOT NULL,
    port         INT NOT NULL,
    db_name      VARCHAR(64) NOT NULL,
    username     VARCHAR(64) NOT NULL,
    password     VARCHAR(128) NOT NULL,
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='产品库数据源';

CREATE TABLE IF NOT EXISTS bm_physical_table (
    id            BIGINT PRIMARY KEY AUTO_INCREMENT,
    ds_code       VARCHAR(64) NOT NULL,
    table_name    VARCHAR(128) NOT NULL,
    table_comment VARCHAR(512),
    scanned_at    DATETIME,
    UNIQUE KEY uk_ds_table (ds_code, table_name)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='物理表快照';

CREATE TABLE IF NOT EXISTS bm_physical_column (
    id               BIGINT PRIMARY KEY AUTO_INCREMENT,
    ds_code          VARCHAR(64) NOT NULL,
    table_name       VARCHAR(128) NOT NULL,
    column_name      VARCHAR(128) NOT NULL,
    data_type        VARCHAR(64),
    column_comment   VARCHAR(512),
    is_pk            TINYINT DEFAULT 0,
    ordinal_position INT DEFAULT 0,
    UNIQUE KEY uk_ds_col (ds_code, table_name, column_name)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='物理列快照';

CREATE TABLE IF NOT EXISTS bm_mapping (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    ds_code      VARCHAR(64)  NOT NULL,
    table_name   VARCHAR(128) NOT NULL,
    column_name  VARCHAR(128) NOT NULL,
    concept_code VARCHAR(64)  NOT NULL,
    attr_code    VARCHAR(64)  NOT NULL,
    value_map    VARCHAR(1024) COMMENT '值字典映射JSON，如 {"2":"已取消"}',
    confirmed    TINYINT DEFAULT 0 COMMENT '是否人工确认',
    source       VARCHAR(16) DEFAULT 'MANUAL' COMMENT 'MANUAL/AI',
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_map (ds_code, table_name, column_name, concept_code, attr_code)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='物理列-概念属性映射';

CREATE TABLE IF NOT EXISTS link_node (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    node_type    VARCHAR(16) NOT NULL COMMENT 'TICKET/REQUIREMENT/CHANGE/TESTCASE/DEPLOY',
    ref_no       VARCHAR(64) NOT NULL UNIQUE COMMENT '单号',
    title        VARCHAR(256) NOT NULL,
    concept_code VARCHAR(64) NOT NULL COMMENT '挂靠概念（链路中枢）',
    status       VARCHAR(32),
    occurred_at  DATETIME,
    payload      TEXT COMMENT '扩展字段JSON',
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    KEY idx_concept (concept_code),
    KEY idx_type (node_type)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='链路节点（需求-研发-测试-运维-客服）';

CREATE TABLE IF NOT EXISTS rca_case (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    case_no      VARCHAR(64) NOT NULL UNIQUE,
    ticket_ref   VARCHAR(64) NOT NULL COMMENT '来源客服工单',
    concept_code VARCHAR(64) NOT NULL,
    status       VARCHAR(16) DEFAULT 'RUNNING' COMMENT 'RUNNING/DONE/FAILED',
    conclusion   TEXT,
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    finished_at  DATETIME
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='根因分析案例';

CREATE TABLE IF NOT EXISTS rca_step (
    id          BIGINT PRIMARY KEY AUTO_INCREMENT,
    case_id     BIGINT NOT NULL,
    step_no     INT NOT NULL,
    step_name   VARCHAR(128) NOT NULL,
    step_type   VARCHAR(16) NOT NULL COMMENT 'TRAVERSE/PROBE/LINK/REPORT',
    sql_text    TEXT COMMENT '实际执行的SQL',
    hit_count   INT DEFAULT 0,
    result_json TEXT COMMENT '探针结果快照JSON',
    status      VARCHAR(16) DEFAULT 'SUCCESS',
    started_at  DATETIME,
    finished_at DATETIME,
    KEY idx_case (case_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='根因分析步骤（证据链）';

CREATE TABLE IF NOT EXISTS rca_report (
    id               BIGINT PRIMARY KEY AUTO_INCREMENT,
    case_id          BIGINT NOT NULL UNIQUE,
    root_cause       TEXT COMMENT '根因结论',
    evidence_json    TEXT COMMENT '证据链JSON',
    impact_json      TEXT COMMENT '影响面JSON',
    suggestions_json TEXT COMMENT '整改建议JSON',
    llm_used         TINYINT DEFAULT 0 COMMENT '报告是否由LLM生成',
    created_at       DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='根因分析报告';

ALTER TABLE bm_metric
    ADD COLUMN ds_code         VARCHAR(64)  COMMENT '探针执行数据源',
    ADD COLUMN probe_sql       TEXT         COMMENT '实测SQL（须返回单个数值）',
    ADD COLUMN warn_threshold  INT          COMMENT '告警阈值（实测值>阈值即告警）',
    ADD COLUMN last_val        INT          COMMENT '最近实测值',
    ADD COLUMN last_eval_at    DATETIME     COMMENT '最近实测时间';

CREATE TABLE IF NOT EXISTS bm_rule (
    id          BIGINT PRIMARY KEY AUTO_INCREMENT,
    rule_code   VARCHAR(64) NOT NULL UNIQUE,
    name        VARCHAR(128) NOT NULL,
    concept_code VARCHAR(64) NOT NULL COMMENT '约束的概念',
    rule_type   VARCHAR(16) NOT NULL COMMENT '约束/推导/校验',
    expression  TEXT NOT NULL COMMENT '规则的声明式表达（业务语言）',
    metric_code VARCHAR(64) COMMENT '关联的可执行指标（规则→探针）',
    severity    VARCHAR(8) DEFAULT '中' COMMENT '高/中/低',
    owner       VARCHAR(64),
    status      VARCHAR(16) DEFAULT 'DRAFT',
    version     INT DEFAULT 1,
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='业务规则（声明式）';

CREATE TABLE IF NOT EXISTS bm_action (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    action_code  VARCHAR(64) NOT NULL UNIQUE,
    name         VARCHAR(128) NOT NULL COMMENT '动作动词，如：取消医嘱',
    concept_code VARCHAR(64) NOT NULL COMMENT '作用对象概念',
    from_status  VARCHAR(64) COMMENT '前置状态（空=无前置）',
    to_status    VARCHAR(64) NOT NULL COMMENT '目标状态',
    trigger_desc VARCHAR(256) COMMENT '触发方/触发条件',
    description  VARCHAR(512),
    status       VARCHAR(16) DEFAULT 'DRAFT',
    version      INT DEFAULT 1,
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='业务动作（概念状态机）';

CREATE TABLE IF NOT EXISTS bm_release (
    id            BIGINT PRIMARY KEY AUTO_INCREMENT,
    version_tag   VARCHAR(32) NOT NULL UNIQUE COMMENT '版本号 v1.0/v1.1...',
    change_summary VARCHAR(512),
    element_count INT COMMENT '快照元素总数',
    snapshot_json LONGTEXT COMMENT '发布时全部已发布元素的快照',
    released_by   VARCHAR(64),
    created_at    DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='本体版本发布';

CREATE TABLE IF NOT EXISTS bm_llm_log (
    id               BIGINT PRIMARY KEY AUTO_INCREMENT,
    call_type        VARCHAR(32) COMMENT 'MAPPING_SUGGEST/SEARCH_ANSWER/RCA_REPORT/IMPACT_ADVICE',
    model            VARCHAR(64),
    ontology_version VARCHAR(32) COMMENT '调用时使用的本体版本',
    prompt_digest    VARCHAR(256) COMMENT '提示词摘要',
    latency_ms       BIGINT,
    success          TINYINT,
    err_msg          VARCHAR(512),
    created_at       DATETIME DEFAULT CURRENT_TIMESTAMP,
    KEY idx_type (call_type),
    KEY idx_created (created_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='LLM调用审计';

CREATE TABLE IF NOT EXISTS bm_axiom (
    id          BIGINT PRIMARY KEY AUTO_INCREMENT,
    axiom_code  VARCHAR(32) NOT NULL UNIQUE,
    subject     VARCHAR(128) NOT NULL COMMENT '主语（概念或限定表达式）',
    predicate   VARCHAR(32)  NOT NULL COMMENT '谓词动词',
    object      VARCHAR(128) NOT NULL COMMENT '宾语',
    axiom_type  VARCHAR(16)  NOT NULL COMMENT '依赖/互斥/支撑/因果/继承',
    description VARCHAR(512),
    status      VARCHAR(16) DEFAULT 'PUBLISHED',
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='本体公理';

ALTER TABLE bm_term
    ADD COLUMN code_system   VARCHAR(32) COMMENT '编码体系：平台标准/SNOMED CT/ICD-10',
    ADD COLUMN standard_code VARCHAR(32) COMMENT '标准编码';

ALTER TABLE bm_rule
    ADD COLUMN engine    VARCHAR(16) COMMENT '执行引擎：QC=质控规则引擎',
    ADD COLUMN expr_json TEXT        COMMENT '规则表达式JSON（引擎解释执行，新规则免开发）';

CREATE TABLE IF NOT EXISTS bm_gov_rule (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    rule_code VARCHAR(32) NOT NULL UNIQUE,
    rule_name VARCHAR(64) NOT NULL,
    rule_type VARCHAR(24) NOT NULL COMMENT 'PK_UNIQUE/NOT_NULL/DICT_CONSISTENT/REF_INTACT/STOCK_BALANCE',
    concept_code VARCHAR(32) NOT NULL COMMENT '挂在哪个概念上（治理规则是本体产物）',
    severity VARCHAR(8) NOT NULL DEFAULT '中',
    expr_json TEXT NOT NULL COMMENT '规则表达式（编译为探针SQL）',
    status VARCHAR(16) NOT NULL DEFAULT 'PUBLISHED',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) COMMENT '数据治理规则：挂接概念、经映射编译为真实SQL探针';

CREATE TABLE IF NOT EXISTS bm_gov_scan (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    scan_time DATETIME NOT NULL,
    duration_ms BIGINT NOT NULL COMMENT '实测耗时（毫秒）',
    rule_count INT NOT NULL,
    issue_count INT NOT NULL,
    quality_score INT NOT NULL COMMENT '质量分 0-100（按规则严重度加权通过率）'
) COMMENT '治理扫描执行记录';

CREATE TABLE IF NOT EXISTS bm_gov_issue (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    scan_id BIGINT NOT NULL COMMENT '所属扫描',
    rule_code VARCHAR(32) NOT NULL,
    rule_name VARCHAR(64) NOT NULL,
    rule_type VARCHAR(24) NOT NULL,
    severity VARCHAR(8) NOT NULL,
    concept_code VARCHAR(32) NOT NULL,
    ds_code VARCHAR(64) NOT NULL,
    table_name VARCHAR(128) NOT NULL,
    hit_count INT NOT NULL COMMENT '命中行数',
    sample_json TEXT COMMENT '样例行（最多5条）',
    status VARCHAR(8) NOT NULL DEFAULT '未处理' COMMENT '未处理/已处理',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_issue_scan (scan_id)
) COMMENT '治理扫描发现的数据问题';

CREATE TABLE IF NOT EXISTS link_rel (
    id          BIGINT PRIMARY KEY AUTO_INCREMENT,
    from_ref_no VARCHAR(64)  NOT NULL COMMENT '上游节点单号（源头/原因侧）',
    to_ref_no   VARCHAR(64)  NOT NULL COMMENT '下游节点单号（结果/闭环侧）',
    rel_type    VARCHAR(32)  NOT NULL COMMENT 'CAUSES/TRIGGERS/LEADS_TO/COVERED_BY/SHIPPED_BY/CLOSED_BY/RELATES',
    remark      VARCHAR(256) COMMENT '关系说明，如来源RCA案例号',
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_rel (from_ref_no, to_ref_no, rel_type),
    KEY idx_from (from_ref_no),
    KEY idx_to (to_ref_no)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='链路节点边（节点级追溯）';

ALTER TABLE bm_relation
    ADD COLUMN is_symmetric          TINYINT(1)  NOT NULL DEFAULT 0 COMMENT '对称公理：A→B 蕴含 B→A',
    ADD COLUMN is_transitive         TINYINT(1)  NOT NULL DEFAULT 0 COMMENT '传递公理：A→B→C 蕴含 A→C（partOf/属于类）',
    ADD COLUMN is_functional         TINYINT(1)  NOT NULL DEFAULT 0 COMMENT '函数公理：同一主语至多一个宾语',
    ADD COLUMN is_inverse_functional TINYINT(1)  NOT NULL DEFAULT 0 COMMENT '逆函数公理：同一宾语至多一个主语',
    ADD COLUMN is_asymmetric         TINYINT(1)  NOT NULL DEFAULT 0 COMMENT '反对称公理：A→B 禁止 B→A',
    ADD COLUMN inverse_of            VARCHAR(64) NULL COMMENT '互逆关系的 relation_name',
    ADD COLUMN iri                   VARCHAR(255) NULL COMMENT '外部本体 IRI（OWL 导入对齐用，与平台内部键分离）',
    ADD UNIQUE KEY uk_relation_iri (iri);

CREATE TABLE IF NOT EXISTS bm_concept_disjoint (
    id             BIGINT PRIMARY KEY AUTO_INCREMENT,
    concept_a_code VARCHAR(64) NOT NULL COMMENT '概念A编码',
    concept_b_code VARCHAR(64) NOT NULL COMMENT '概念B编码',
    definition     TEXT COMMENT '互斥理由（来源公理/业务口径）',
    status         VARCHAR(16) DEFAULT 'PUBLISHED' COMMENT 'DRAFT/REVIEW/PUBLISHED/DEPRECATED',
    created_at     DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at     DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uk_disjoint_pair (concept_a_code, concept_b_code)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='概念互斥公理（对称语义，服务层双向查询）';

ALTER TABLE bm_concept
    ADD COLUMN iri VARCHAR(255) NULL COMMENT '外部本体 IRI（OWL 导入对齐用）',
    ADD UNIQUE KEY uk_concept_iri (iri);

CREATE TABLE IF NOT EXISTS bm_ontology_miss (
    id                   BIGINT PRIMARY KEY AUTO_INCREMENT,
    term                 VARCHAR(128) NOT NULL COMMENT '未命中的说法原文（搜索查询词 / 物理列注释或列名）',
    kind                 VARCHAR(16)  NOT NULL COMMENT 'CONCEPT/ATTRIBUTE',
    source               VARCHAR(16)  NOT NULL COMMENT 'SEARCH/MAPPING_AI',
    count                INT          NOT NULL DEFAULT 1 COMMENT '累计出现次数（忽略后照涨）',
    dismissed            TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '已忽略（标记，不删除）',
    dismiss_reason       VARCHAR(255) NULL COMMENT '忽略理由',
    adopted_concept_code VARCHAR(64)  NULL COMMENT '采纳后落的概念 code',
    revoked              TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '采纳被撤销（概念置 DEPRECATED，miss 回待处理池）',
    first_seen           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次出现',
    last_seen            DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最近出现',
    UNIQUE KEY uk_miss_term (term, kind),
    KEY idx_miss_board (dismissed, count)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='本体增长回路：词表外说法采集池';

ALTER TABLE bm_ontology_miss
    ADD COLUMN adopted_as VARCHAR(16) NULL COMMENT '采纳形态：CONCEPT 新建概念 / TERM 挂为现有概念术语' AFTER adopted_concept_code;

CREATE TABLE IF NOT EXISTS bm_concept_parent (
    id          BIGINT PRIMARY KEY AUTO_INCREMENT,
    child_code  VARCHAR(64) NOT NULL COMMENT '子概念',
    parent_code VARCHAR(64) NOT NULL COMMENT '父概念',
    is_primary  TINYINT(1)  NOT NULL DEFAULT 0 COMMENT '主父（展示用），同 child 唯一',
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_child_parent (child_code, parent_code)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='概念多父继承（subClassOf 结构化）';

CREATE TABLE IF NOT EXISTS bm_relation_closure (
    id            BIGINT PRIMARY KEY AUTO_INCREMENT,
    relation_name VARCHAR(64) NOT NULL COMMENT '传递关系名（如 属于）',
    from_concept  VARCHAR(64) NOT NULL,
    to_concept    VARCHAR(64) NOT NULL,
    depth         INT         NOT NULL COMMENT '最短路径跳数',
    UNIQUE KEY uk_closure (relation_name, from_concept, to_concept)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='传递关系闭包（发布时物化）';

CREATE TABLE IF NOT EXISTS bm_user (
    id            BIGINT PRIMARY KEY AUTO_INCREMENT,
    username      VARCHAR(64)  NOT NULL UNIQUE COMMENT '登录名',
    password_hash VARCHAR(100) NOT NULL COMMENT 'BCrypt 口令哈希',
    display_name  VARCHAR(64)  COMMENT '显示名',
    role          VARCHAR(16)  NOT NULL DEFAULT 'VIEWER' COMMENT 'ADMIN/EDITOR/VIEWER',
    created_at    DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='平台用户';

CREATE TABLE IF NOT EXISTS bm_alert_notice (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    metric_code  VARCHAR(64)  NOT NULL COMMENT '越限指标编码',
    metric_name  VARCHAR(128) COMMENT '指标名称',
    actual_value INT          NULL COMMENT '实测值（探针失败为 NULL）',
    threshold    INT          NULL COMMENT '告警阈值',
    message      VARCHAR(512) COMMENT '告警文案',
