    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    KEY idx_notice_status (status, metric_code)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='指标巡检平台内告警';

CREATE TABLE IF NOT EXISTS bm_inspect_run (
    id              BIGINT PRIMARY KEY AUTO_INCREMENT,
    evaluated       INT NOT NULL COMMENT '本次评估指标数',
    alarmed         INT NOT NULL COMMENT '越限/异常数',
    notices_created INT NOT NULL COMMENT '新生成告警数（幂等去重后）',
    created_at      DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='巡检执行记录';

CREATE TABLE IF NOT EXISTS bm_cs_feedback (
    id         BIGINT PRIMARY KEY AUTO_INCREMENT,
    question   VARCHAR(512) NOT NULL COMMENT '用户原始问题',
    intent     VARCHAR(32)  COMMENT '当时命中的意图标签',
    router     VARCHAR(16)  COMMENT 'LLM/RULE/SEMANTIC/NONE',
    correct    TINYINT(1)   NOT NULL COMMENT '1 归类正确 / 0 错误',
    comment    VARCHAR(512) NULL COMMENT '备注（可写正确意图）',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    KEY idx_feedback_correct (correct, id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='客服问答路由反馈';

ALTER TABLE bm_release
    ADD COLUMN approved_by VARCHAR(64) NULL COMMENT '审批人（评审员/管理员）',
    ADD COLUMN approved_at DATETIME   NULL COMMENT '审批时间';

ALTER TABLE bm_user
    MODIFY COLUMN role VARCHAR(16) NOT NULL DEFAULT 'VIEWER'
        COMMENT 'ADMIN/EDITOR/REVIEWER/VIEWER';

ALTER TABLE bm_mapping
    ADD COLUMN status     VARCHAR(16) NOT NULL DEFAULT 'ACTIVE'
        COMMENT '生命周期: PROPOSED/ACTIVE/DEPRECATED',
    ADD COLUMN updated_by VARCHAR(64)  NULL COMMENT '最近操作人',
    ADD COLUMN updated_at DATETIME     NULL COMMENT '最近操作时间';

CREATE TABLE IF NOT EXISTS bm_mapping_log (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    mapping_id  BIGINT       NOT NULL COMMENT 'bm_mapping.id',
    action      VARCHAR(16)  NOT NULL COMMENT 'CREATE/UPDATE/TRANSITION/DELETE',
    before_json TEXT         NULL COMMENT '变更前快照',
    after_json  TEXT         NULL COMMENT '变更后快照',
    operator    VARCHAR(64)  NULL COMMENT '操作人',
    created_at  DATETIME     DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
    KEY idx_mapping_log_mid (mapping_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='映射变更留痕';

CREATE TABLE IF NOT EXISTS bm_recon_diff (
    id               BIGINT AUTO_INCREMENT PRIMARY KEY,
    run_id           VARCHAR(40)  NOT NULL COMMENT '核对批次号',
    direction        VARCHAR(8)   NOT NULL COMMENT 'A=发药×缴费 B=缴费×发药',
    state_code       VARCHAR(40)  NOT NULL COMMENT '语义档：VIOLATION_PREPAY_BYPASS/RETURNED_PENDING_REFUND/STUCK_BACKLOG/IN_FLIGHT/NIGHTLY_CANCEL/CANCELLED_AFTER_PAY',
    severity         VARCHAR(16)  NOT NULL COMMENT 'VIOLATION/WATCH/NORMAL',
    attribution      VARCHAR(256) NULL COMMENT '归因说明',
    suggested_action VARCHAR(256) NULL COMMENT '建议动作',
    patient_no       VARCHAR(64)  NULL COMMENT '业务键（保留可下钻，不脱敏）',
    order_id         VARCHAR(64)  NULL,
    item_name        VARCHAR(128) NULL,
    created_at       DATETIME     DEFAULT CURRENT_TIMESTAMP,
    KEY idx_recon_run (run_id),
    KEY idx_recon_state (state_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='跨库核对差异登记';

CREATE TABLE IF NOT EXISTS bm_clarify_task (
    id               BIGINT AUTO_INCREMENT PRIMARY KEY,
    scene            VARCHAR(16)  NOT NULL COMMENT 'ANALYTICS（MVP 仅此值；CS 预留）',
    origin_question  VARCHAR(512) NOT NULL COMMENT '原问题（resume 锚点）',
    reason           VARCHAR(512) NULL COMMENT 'UNANSWERABLE reason（LLM 原话）',
    gap_type         VARCHAR(16)  NOT NULL COMMENT '仅 AMBIGUITY 会建任务，列保留以便扩展',
    clarify_question VARCHAR(512) NOT NULL COMMENT '追问话术：LLM 生成，无 Key 降级模板拼装',
    status           VARCHAR(16)  NOT NULL COMMENT 'PENDING / RESOLVED / GAVE_UP',
    supplement       VARCHAR(1024) NULL COMMENT '用户补充原文（多轮以；拼接，RESOLVED/GAVE_UP 后保留作证据）',
    rounds           INT NOT NULL DEFAULT 0 COMMENT '已发出的追问轮数，上限 2',
    miss_id          BIGINT NULL COMMENT 'GAVE_UP 时关联回流的 bm_ontology_miss.id',
    created_at       DATETIME NULL,
    answered_at      DATETIME NULL,
    closed_at        DATETIME NULL,
    KEY idx_clarify_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='问数澄清任务（可挂起可续跑）';

CREATE TABLE IF NOT EXISTS bm_qa_trace (
    id               BIGINT AUTO_INCREMENT PRIMARY KEY,
    trace_id         VARCHAR(24)  NOT NULL COMMENT 'QA-<时间戳>-<rand6>',
    scene            VARCHAR(16)  NOT NULL COMMENT 'ANALYTICS / CS',
    question         VARCHAR(512) NOT NULL COMMENT '用户原问题',
    ds_code          VARCHAR(32)  NULL COMMENT '执行数据源',
    used_tables      VARCHAR(256) NULL COMMENT '实际用到的物理表（逗号分隔）',
    sql_text         VARCHAR(1024) NULL COMMENT '白名单校验后实际执行的 SQL',
    semantics        VARCHAR(512) NULL COMMENT '语义计划说明（查了什么、用了哪些概念）',
    matched_concepts VARCHAR(256) NULL COMMENT '命中的 PUBLISHED 概念 code（逗号分隔）',
    row_count        INT NULL COMMENT '真实返回行数',
    answer           TEXT NULL COMMENT '最终结论',
    answer_source    VARCHAR(16)  NOT NULL COMMENT 'LLM / TEMPLATE（诚实标注作答来源）',
    duration_ms      INT NULL COMMENT 'SQL 执行耗时',
    created_at       DATETIME DEFAULT CURRENT_TIMESTAMP,
    KEY idx_qatrace_trace (trace_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='问数答案证据链';

CREATE TABLE IF NOT EXISTS bm_proposal_run (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    scanned     INT NOT NULL COMMENT '候选 miss 数（选样后）',
    generated_cnt INT NOT NULL COMMENT '生成提案数（同判定归并后）',
    llm_failed  INT NOT NULL COMMENT 'LLM 失败/判定失效丢弃的 miss 数',
    message     VARCHAR(255) NULL COMMENT '本次运行说明（全失败时给原因）',
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='提案生成运行记录';

CREATE TABLE IF NOT EXISTS bm_ontology_proposal (
    id                  BIGINT AUTO_INCREMENT PRIMARY KEY,
    primary_miss_id     BIGINT       NOT NULL COMMENT '主信号 miss id（组内 count 最高）',
    miss_ids            JSON         NOT NULL COMMENT '聚类归并的全部 miss id（含主信号）',
    term                VARCHAR(128) NOT NULL COMMENT '代表说法（主信号原文）',
    signal_count        INT NOT NULL DEFAULT 1 COMMENT '信号总热度（组内 count 求和）',
    action              VARCHAR(16)  NOT NULL COMMENT 'AI 预审判定：NEW_CONCEPT / ATTACH_TERM',
    target_concept_code VARCHAR(64)  NULL COMMENT 'ATTACH_TERM 的挂靠目标概念编码',
    suggestion_json     JSON         NULL COMMENT '候选卡：code/name/domainCode/definition/reason/confidence/warnings',
    status              VARCHAR(16)  NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING / ADOPTED / REJECTED',
    decided_by          VARCHAR(64)  NULL COMMENT '裁决人',
    decided_at          DATETIME     NULL COMMENT '裁决时间',
    reject_reason       VARCHAR(255) NULL COMMENT '驳回理由',
    run_id              BIGINT       NOT NULL COMMENT '生成批次 bm_proposal_run.id',
    created_at          DATETIME DEFAULT CURRENT_TIMESTAMP,
    KEY idx_proposal_status (status),
    KEY idx_proposal_miss (primary_miss_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI 提案队列（本体增长回路 L2）';

CREATE TABLE IF NOT EXISTS bm_lab_run (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    experiment_key VARCHAR(32)   NOT NULL COMMENT '实验键 GATE/ADVERSARIAL/REFUND/TRAVERSE',
    question       VARCHAR(500)  NOT NULL COMMENT '三臂同题的问题文本',
    force_execute  TINYINT(1)    NOT NULL DEFAULT 1 COMMENT 'B 臂强制执行开关(允许写 SQL)',
    status         VARCHAR(20)   NOT NULL COMMENT 'QUEUED/RUNNING/DONE/FAILED',
    payload_json   MEDIUMTEXT             COMMENT '三臂结果:A/B/C 各自 status+answer+steps+llmCalls+elapsedMs+anchorsCited',
    error_msg      VARCHAR(1000)          COMMENT '整体失败原因',
    created_at     DATETIME      NOT NULL COMMENT '起跑时间',
    finished_at    DATETIME               COMMENT 'DONE/FAILED 落定时间',
    KEY idx_lab_run_exp (experiment_key),
    KEY idx_lab_run_created (created_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='AI 对比实验室运行记录';

CREATE TABLE IF NOT EXISTS bm_simulation_run (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    scenario     VARCHAR(32)   NOT NULL COMMENT '场景键 STOCK_CUT',
    status       VARCHAR(20)   NOT NULL COMMENT 'QUEUED/RUNNING/DONE/FAILED',
    payload_json MEDIUMTEXT             COMMENT '施加+波及步骤+观察diff 整体一次写',
    error_msg    VARCHAR(1000)          COMMENT '整体失败原因',
    created_at   DATETIME      NOT NULL COMMENT '起跑时间',
    finished_at  DATETIME               COMMENT 'DONE/FAILED 落定时间',
    KEY idx_sim_run_scenario (scenario),
    KEY idx_sim_run_created (created_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='推演沙盘运行记录';

ALTER TABLE bm_llm_log ADD COLUMN provider VARCHAR(32) AFTER call_type;

CREATE TABLE IF NOT EXISTS bm_document (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    title        VARCHAR(200) NOT NULL COMMENT '文档标题',
    doc_type     VARCHAR(16)  NOT NULL COMMENT 'MD/PDF/DOCX/TXT',
    source       VARCHAR(16)  DEFAULT 'UPLOAD' COMMENT 'UPLOAD/SEED',
    status       VARCHAR(16)  DEFAULT 'DRAFT' COMMENT 'DRAFT/REVIEW/PUBLISHED/DEPRECATED',
    version      INT DEFAULT 1 COMMENT '版本号（同标题重传时递增，旧版置 DEPRECATED）',
    owner        VARCHAR(64) COMMENT '文档负责人',
    uploaded_by  VARCHAR(64) COMMENT '上传人',
    file_size    INT COMMENT '原文件字节数',
    content_hash VARCHAR(64) COMMENT 'SHA-256 内容指纹（重复上传识别）',
    content_text LONGTEXT COMMENT '解析出的纯文本留存（供重切分）',
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_doc_status (status),
    KEY idx_doc_hash (content_hash)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='制度文档（知识轨非结构化载体）';

CREATE TABLE IF NOT EXISTS bm_doc_chunk (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    document_id  BIGINT NOT NULL COMMENT '所属文档 id',
    seq          INT NOT NULL COMMENT '片段序号（文档内从 0 起）',
    heading      VARCHAR(500) COMMENT '所属标题路径（如「缴费管理/退费流程」）',
    content      TEXT NOT NULL COMMENT '片段正文（目标约 500 字，相邻重叠 50 字）',
    embedding    JSON NULL COMMENT '向量化结果 JSON 数组（空=未向量化，向量路对该片段关闭）',
    concept_code VARCHAR(64) NULL COMMENT '挂靠概念 code（与本体可空互挂）',
    KEY idx_chunk_doc (document_id),
    FULLTEXT KEY ft_chunk_content (content) WITH PARSER ngram
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='文档片段（检索与引用的最小单元）';

CREATE TABLE IF NOT EXISTS bm_knowledge (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    code         VARCHAR(64)  NOT NULL UNIQUE COMMENT '条目编码（全局唯一）',
    title        VARCHAR(200) NOT NULL COMMENT '条目标题',
    content      TEXT NOT NULL COMMENT '条目正文（专家经验文案）',
    applies_to   VARCHAR(200) COMMENT '适用场景标签（逗号分隔概念码，如 FEE_DETAIL,DISPENSE）',
    concept_code VARCHAR(64) NULL COMMENT '挂靠概念 code（可空互挂）',
    source       VARCHAR(16)  DEFAULT 'SEED' COMMENT 'SEED/ADMIN',
    status       VARCHAR(16)  DEFAULT 'DRAFT' COMMENT 'DRAFT/REVIEW/PUBLISHED/DEPRECATED',
    version      INT DEFAULT 1,
    owner        VARCHAR(64) COMMENT '条目负责人',
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='知识条目（结构化专家经验）';

ALTER TABLE bm_qa_trace ADD COLUMN matched_docs VARCHAR(500)
    COMMENT '命中文档片段 docId:seq 逗号分隔（可空）' AFTER matched_concepts;

CREATE TABLE bm_reconcile_group (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    group_code    VARCHAR(64)  NOT NULL COMMENT '对账组编码',
    name          VARCHAR(128) NOT NULL COMMENT '业务指标名(如:月出院人数)',
    definition    VARCHAR(512) NULL COMMENT '分歧背景说明(给对账会看)',
    metric_codes  VARCHAR(512) NOT NULL COMMENT '参与口径的指标编码,逗号分隔,至少2个',
    drill_ds_code VARCHAR(64)  NULL COMMENT '明细下钻执行的数据源编码(空=不下钻)',
    drill_sql     TEXT         NULL COMMENT '差额明细下钻SQL(可选,只读,返回明细行)',
    owner         VARCHAR(64)  NULL COMMENT '对账牵头科室',
    created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    UNIQUE KEY uk_group_code (group_code)
) COMMENT='对账口径组(同一业务指标的多口径绑定)';

CREATE TABLE bm_reconcile_run (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    group_code  VARCHAR(64)  NOT NULL COMMENT '对账组编码',
    values_json VARCHAR(1024) NOT NULL COMMENT '各口径实测值 JSON,如 {"PILOT_DISCHARGE_MED":153}',
    diff_value  BIGINT       NULL COMMENT '口径间差额(最大-最小;有口径实测失败则为 NULL)',
    drill_json  TEXT         NULL COMMENT '下钻明细行 JSON(最多200行,NULL=未配下钻)',
    drill_count INT          NULL COMMENT '下钻明细行数(-1=下钻执行失败,NULL=未配下钻)',
    error_msg   VARCHAR(500) NULL COMMENT '失败口径信息(空=全部口径实测成功)',
    ran_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '运行时间',
    KEY idx_run_group (group_code)
) COMMENT='对账运行记录(每次跑组落一条)';

ALTER TABLE bm_reconcile_group
    ADD COLUMN dispute_status VARCHAR(16) NOT NULL DEFAULT 'OPEN'
        COMMENT '分歧状态:OPEN待认领/CLAIMED对账中/RESOLVED已裁决',
    ADD COLUMN dispute_owner VARCHAR(64) NULL
        COMMENT '认领人(谁在牵头对这笔分歧)',
    ADD COLUMN verdict VARCHAR(512) NULL
        COMMENT '裁决结论:以哪侧口径为准(一句话,给报表用)',
    ADD COLUMN verdict_note VARCHAR(512) NULL
        COMMENT '裁决依据/备注(对账会上怎么定的)',
    ADD COLUMN verdict_at DATETIME NULL COMMENT '裁决时间';

ALTER TABLE bm_qa_trace ADD COLUMN plan_mode VARCHAR(16) NULL COMMENT '计划模式 QUERY/METRIC(旧行 NULL 视作 QUERY)';

ALTER TABLE bm_reconcile_group
    ADD COLUMN buckets_json TEXT NULL COMMENT '归因桶配置 JSON:[{label,dsCode,sql,sign}]',
    ADD COLUMN scheduled TINYINT NOT NULL DEFAULT 0 COMMENT '是否挂每日巡检(0/1)',
    ADD COLUMN claimed_by VARCHAR(64) NULL COMMENT '认领人登录名(旧行 NULL=自报时代,展示回退 dispute_owner)',
    ADD COLUMN resolved_by VARCHAR(64) NULL COMMENT '裁决人登录名';

ALTER TABLE bm_reconcile_run ADD COLUMN buckets_json TEXT NULL COMMENT '归因桶结果 JSON:{buckets:[{label,sign,count,error}],sum,matchesDiff}';
